    event.preventDefault();
    const save = dialog.querySelector('[data-save]'); if (save.disabled) return;
    const next = { ...cfg };
    fields.querySelectorAll('[data-field]').forEach((input) => { next[input.name] = input.type === 'checkbox' ? input.checked : input.value; });
